ALTER TABLE public.templates ADD COLUMN event_setup jsonb;
CREATE FUNCTION public.my_authored_library_items() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT coalesce(jsonb_agg(x),'[]') FROM (SELECT jsonb_build_object('id',e.id,'kind','event','title',e.title) x FROM events e WHERE e.host_id=auth.uid() UNION ALL SELECT jsonb_build_object('id',r.id,'kind','recipe','title',coalesce(nullif(r.title_en,''),r.title_es)) FROM recipes r WHERE r.created_by=auth.uid() AND r.team_id IS NOT NULL UNION ALL SELECT jsonb_build_object('id',t.id,'kind','track','title',coalesce(nullif(t.title_en,''),t.title_es)) FROM tracks t JOIN teams tm ON tm.id=t.team_id WHERE tm.owner_id=auth.uid() AND t.offer_id IS NULL UNION ALL SELECT jsonb_build_object('id',o.id,'kind','offer','title',coalesce(nullif(o.title_en,''),o.title_es)) FROM offers o WHERE o.host_id=auth.uid() AND o.kind IN ('course','download')) q $$;
CREATE FUNCTION public.export_library_source(_kind text,_id uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE e events; tr tracks; rc recipes; o offers; new_id uuid; setup jsonb; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'forbidden'; END IF;
IF _kind='event' THEN SELECT * INTO e FROM events WHERE id=_id AND host_id=auth.uid(); IF NOT FOUND THEN RAISE EXCEPTION 'forbidden'; END IF;
setup:=jsonb_build_object('title',e.title,'descEn',e.description_en,'descEs',e.description_es,'start','','duration',extract(epoch FROM(e.ends_at-e.starts_at))/60,'place',e.format,'locationName',e.location_name,'address',e.address,'capacityMode',CASE WHEN e.capacity IS NULL THEN 'unlimited' ELSE 'limited' END,'capacity',coalesce(e.capacity::text,''),'price',coalesce(e.price_cents,0)/100.0,'visibility','invite','category',e.category,'categoryLabel',e.category_label,'details',jsonb_build_object('summary_en',e.summary_en,'summary_es',e.summary_es,'language',e.language,'format',e.format,'map_url',e.map_url,'waitlist_enabled',e.waitlist_enabled,'tags',e.tags,'accessibility_notes',e.accessibility_notes,'what_to_bring',e.what_to_bring,'cancellation_policy',e.cancellation_policy,'min_age',e.min_age,'ticket_tiers',coalesce((SELECT jsonb_agg(jsonb_build_object('id',gen_random_uuid(),'name',a->>'name','price_cents',a->'price_cents','quantity',a->'quantity','sale_starts_at',NULL,'sale_ends_at',NULL)) FROM jsonb_array_elements(e.ticket_tiers) a),'[]'),'addons',coalesce((SELECT jsonb_agg(jsonb_build_object('id',gen_random_uuid(),'name',a->>'name','price_cents',a->'price_cents')) FROM jsonb_array_elements(e.addons) a),'[]')));
INSERT INTO templates(team_id,created_by,title,description_en,description_es,is_published,event_setup,copied_from_id,copied_from_author) VALUES(e.team_id,auth.uid(),e.title,e.description_en,e.description_es,false,setup,e.id,e.host_id) RETURNING id INTO new_id;
ELSIF _kind='track' THEN SELECT * INTO tr FROM tracks WHERE id=_id AND offer_id IS NULL AND EXISTS(SELECT 1 FROM teams WHERE id=tracks.team_id AND owner_id=auth.uid()); IF NOT FOUND THEN RAISE EXCEPTION 'forbidden'; END IF; new_id:=public.save_resource_template('track',_id,tr.title_en,tr.title_es);
ELSIF _kind='recipe' THEN SELECT * INTO rc FROM recipes WHERE id=_id AND created_by=auth.uid(); IF NOT FOUND THEN RAISE EXCEPTION 'forbidden'; END IF; new_id:=public.save_resource_template('recipe',_id,rc.title_en,rc.title_es);
ELSIF _kind='offer' THEN SELECT * INTO o FROM offers WHERE id=_id AND host_id=auth.uid() AND kind IN ('course','download'); IF NOT FOUND THEN RAISE EXCEPTION 'forbidden'; END IF; new_id:=public.save_resource_template('offer',_id,o.title_en,o.title_es);
ELSE RAISE EXCEPTION 'unsupported_type'; END IF; RETURN new_id; END $$;
DO $$ DECLARE d text; BEGIN SELECT pg_get_functiondef('public.copy_team_library_item(uuid,text,uuid,uuid,uuid)'::regprocedure) INTO d;
d:=replace(d,'INSERT INTO templates(team_id,created_by,title,description_en', 'IF t.event_setup IS NOT NULL THEN new_id:=public.save_event_builder_draft(_destination,NULL,t.event_setup); result:=jsonb_build_object(''id'',new_id,''target'',''event''); ELSE INSERT INTO templates(team_id,created_by,title,description_en');
d:=replace(d,'result:=jsonb_build_object(''id'',new_id,''target'',''blueprint'');','result:=jsonb_build_object(''id'',new_id,''target'',''blueprint''); END IF;'); EXECUTE d;
END $$;
CREATE FUNCTION public.validate_library_shares() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.shared_team_ids IS DISTINCT FROM OLD.shared_team_ids AND auth.uid() IS NOT NULL THEN IF NEW.created_by IS DISTINCT FROM auth.uid() OR EXISTS(SELECT 1 FROM unnest(NEW.shared_team_ids) x WHERE NOT public.team_channel_access(x)) THEN RAISE EXCEPTION 'forbidden'; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER templates_share_guard BEFORE UPDATE ON public.templates FOR EACH ROW EXECUTE FUNCTION public.validate_library_shares(); CREATE TRIGGER resource_templates_share_guard BEFORE UPDATE ON public.resource_templates FOR EACH ROW EXECUTE FUNCTION public.validate_library_shares();
REVOKE ALL ON FUNCTION public.my_authored_library_items(),public.export_library_source(text,uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.my_authored_library_items(),public.export_library_source(text,uuid) TO authenticated;
CREATE OR REPLACE FUNCTION public.can_use_team_templates(_team uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.team_channel_access(_team) $$;